  id: string
  type?: string
  function: {
    name: string
    arguments: string
  }
}

export interface MessageItem {
  sender_id: string
  sender_name?: string
  role: Role
  timestamp: number
  content: string | ContentItem[]
  tool_calls?: ToolCall[]
  tool_call_id?: string
}

export interface AddRequest {
  session_id: string
  app_id?: string
  project_id?: string
  messages: MessageItem[]
  /** Persist into EverOS's durable buffer without running extraction. */
  defer_extraction?: boolean
}

export interface AddResponse {
  message_count: number
  status: 'accumulated' | 'extracted'
}

export type SearchOwner =
  | { user_id: string; agent_id?: undefined }
  | { agent_id: string; user_id?: undefined }

export interface SearchRequestBase {
  app_id?: string
  project_id?: string
  query: string
  method?: SearchMethod
  top_k?: number
  radius?: number
  min_score?: number
  include_profile?: boolean
  enable_llm_rerank?: boolean
  filters?: unknown
